    return { code: 0, out: `${JSON.stringify({ files, notes }, null, 2)}\n` };
  }
  const { out, shown } = renderContext(g, files, matches, opts);
  session?.saw(shown);
  return { code: 0, out };
}

function indent(text: string): string {
  return text
    .split("\n")
    .map((l) => (l ? `    ${l}` : l))
    .join("\n");
}

